src/styles/threeUiLanding.css.old:
.cova-liquid-metal-signup__fallback {
  position: absolute;
  z-index: 1;
  top: 50%;
  left: 50%;
  display: inline-flex;
  width: var(--cova-liquid-control-width);
  height: 52px;
  align-items: center;
  justify-content: center;
  gap: 0.58rem;
  padding: 0 1.15rem;
  border: 1px solid rgba(111, 150, 255, 0.72);
  border-radius: 999px;
  color: #e8eeff;
  background:
    linear-gradient(110deg, rgba(79, 125, 255, 0.2), rgba(13, 15, 20, 0.96) 42%, rgba(111, 150, 255, 0.16)),
    #0d0f14;
  box-shadow:
    inset 0 1px 0 rgba(232, 238, 255, 0.18),
    0 10px 28px rgba(0, 0, 0, 0.34),
    0 0 24px rgba(79, 125, 255, 0.12);
  font-family: "Inter Tight Variable", "Inter Tight", "Inter", sans-serif;
  font-size: 0.92rem;
  font-weight: 500;
  transform: translate(-50%, -50%);
  transition:
    border-color 160ms ease,
    box-shadow 160ms ease,
    opacity 140ms ease,
    transform 120ms ease;
}

.cova-liquid-metal-signup__fallback svg {
  width: 1rem;
  height: 1rem;
}

.cova-liquid-metal-signup__fallback:hover,
.cova-liquid-metal-signup__fallback:focus-visible {
  border-color: #e8eeff;
  box-shadow:
    inset 0 1px 0 rgba(232, 238, 255, 0.24),
    0 12px 32px rgba(0, 0, 0, 0.4),
    0 0 30px rgba(79, 125, 255, 0.24);
}

.cova-liquid-metal-signup__fallback:active {
  transform: translate(-50%, -48%) scale(0.985);
}

